package dev.annawathe.client.mixin;
import dev.annawathe.api.client.inventory.*; import net.minecraft.client.gui.DrawContext; import net.minecraft.client.gui.screen.ingame.CreativeInventoryScreen; import net.minecraft.client.gui.screen.ingame.AbstractInventoryScreen; import net.minecraft.entity.player.PlayerInventory; import net.minecraft.screen.PlayerScreenHandler; import net.minecraft.text.Text; import org.spongepowered.asm.mixin.Mixin; import org.spongepowered.asm.mixin.injection.At; import org.spongepowered.asm.mixin.injection.Inject; import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
@Mixin(CreativeInventoryScreen.class) public abstract class CreativeInventoryButtonsMixin extends AbstractInventoryScreen<PlayerScreenHandler>{protected CreativeInventoryButtonsMixin(PlayerScreenHandler h,PlayerInventory i,Text t){super(h,i,t);} @Inject(method="init",at=@At("TAIL")) private void annawathe$init(CallbackInfo ci){if(client!=null)InventoryButtonApi.initializeScreen(this,InventoryScreenType.CREATIVE,client.player,textRenderer,w->addDrawableChild(w),width,height,x,y,backgroundWidth,backgroundHeight);} @Inject(method="render",at=@At("TAIL")) private void annawathe$render(DrawContext c,int mx,int my,float d,CallbackInfo ci){InventoryButtonApi.renderScreen(this,c,mx,my,d);} @Inject(method="handledScreenTick",at=@At("TAIL")) private void annawathe$tick(CallbackInfo ci){InventoryButtonApi.tickScreen(this);} @Inject(method="removed",at=@At("HEAD")) private void annawathe$close(CallbackInfo ci){InventoryButtonApi.closeScreen(this);} }
